const raw = $input.first().json.content?.parts?.[0]?.text || "";

function parseJson(rawText) {
  let text = String(rawText || "").trim();
  text = text.replace(/^```json\s*/i, "").replace(/^```\s*/i, "").replace(/```\s*$/i, "").trim();

  try {
    return JSON.parse(text);
  } catch {
    const match = text.match(/\{[\s\S]*\}/);
    if (!match) throw new Error("No JSON object found in Gemini response");
    return JSON.parse(match[0]);
  }
}

try {
  const parsed = parseJson(raw);
  const image = $('Webhook').first().json.body.image;

  return [{
    json: {
      status: "ok",
      image_id: image.id || null,
      type: parsed.type || "other",
      label: parsed.label || "Reference image",
      description: parsed.description || "",
      usage_note: parsed.usage_note || "",
      sensitive_note: parsed.sensitive_note || ""
    }
  }];
} catch (error) {
  const image = $('Webhook').first().json.body.image || {};

  return [{
    json: {
      status: "fail",
      image_id: image.id || null,
      stage: "reference_image_analysis",
      error: error.message,
      raw_preview: raw.slice(0, 500)
    }
  }];
}
